{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "Imipramine, a basic tricyclic amine with a propylamine side chain, showed 29-77% systemic availability after oral dosing in humans, supporting F >= 20% for the similarly basic diamine query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Desipramine, a close tricyclic analogue with a secondary amine side chain, had a mean absolute oral bioavailability of 38% in healthy volunteers, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Fentanyl, which shares the N-phenyl amine and aromatic hydrophobic character of the query, had an absolute oral bioavailability of 31% in healthy volunteers, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Amitriptyline, a tricyclic antidepressant with a dimethylaminopropylidene chain, showed absolute oral bioavailability of about 96% in one human study and generally 30-60% in others, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Nortriptyline, a secondary-amine tricyclic antidepressant, had absolute oral bioavailability of 46-70% in humans, supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Rotigotine has low oral bioavailability in humans, but this is driven by a phenolic group and extensive first-pass metabolism that the query lacks, so it provides only weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high oral bioavailability (F >= 20%) because the query is a moderately lipophilic diamine with low TPSA and MW 294, and multiple structurally related basic amines (imipramine, desipramine, fentanyl, amitriptyline, nortriptyline) show human oral bioavailability mostly 30-70%, all above the threshold. The low-F rotigotine evidence is less transferable due to its phenolic group and extensive first-pass metabolism, which are absent in the query.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "Morgan similarities to all evidence molecules are low (<0.3), limiting quantitative transferability.",
    "No direct data on permeability, first-pass metabolism, or transporter effects for the query.",
    "Ionization state at physiological pH is uncertain; the prior suggests possible dicationic character, but the aniline-type nitrogen may be largely unprotonated."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

